// ─────────────────────────────────────────────
// EXTRAER DATOS DEL MENSAJE — Evolution API
// Soporta: wrapper n8n { body: {...} } o payload directo
// ─────────────────────────────────────────────
const raw = $input.first().json;

// n8n con responseMode:responseNode envuelve en { headers, params, query, body, ... }
// Intentamos ambas capas para ser robustos
const p = (raw.body && typeof raw.body === 'object' && !Array.isArray(raw.body))
  ? raw.body
  : raw;

// ── Ignorar status updates sin texto (receipts de lectura/entrega)
// Solo ignorar si NO trae mensaje de texto
const msg   = p.message || {};
const texto =
  msg.conversation ||
  msg.extendedTextMessage?.text ||
  msg.imageMessage?.caption ||
  msg.buttonsResponseMessage?.selectedDisplayText ||
  msg.listResponseMessage?.title || '';

// Si el campo status indica que es solo un receipt Y no hay texto real → ignorar
const status = p.status || '';
if (status && !texto.trim()) {
  return [{ json: { ignorar: true, razon: 'receipt:' + status } }];
}

// ── Ignorar mensajes propios (fromMe)
const key    = p.key || {};
const fromMe = p.fromMe === true || key.fromMe === true;
if (fromMe) return [{ json: { ignorar: true, razon: 'fromMe' } }];

// ── Sin texto → ignorar
if (!texto.trim()) return [{ json: { ignorar: true, razon: 'sin_texto' } }];

// ── Obtener remoteJid (número del cliente)
// En modo LID el remoteJid puede estar en key.remoteJidAlt o participant
const remoteJid =
  p.remoteJid ||
  key.remoteJid ||
  key.remoteJidAlt ||
  p.participant ||
  '';

const numero = remoteJid
  .replace('@s.whatsapp.net', '')
  .replace('@lid', '')
  .replace('@g.us', '');

if (!numero) return [{ json: { ignorar: true, razon: 'sin_numero' } }];

// ── Construir remoteJid normalizado para enviar respuesta
const remoteJidNorm = remoteJid.includes('@')
  ? remoteJid
  : numero + '@s.whatsapp.net';

return [{
  json: {
    ignorar:   false,
    numero,
    remoteJid: remoteJidNorm,
    nombre:    p.pushName || '',
    texto:     texto.trim(),
    timestamp: p.messageTimestamp || Math.floor(Date.now() / 1000)
  }
}];

const numero = $input.first().json.numero;
const staticData = $getWorkflowStaticData('global');

if (!staticData.clientes) staticData.clientes = {};

const cliente = staticData.clientes[numero] || {
  numero,
  historial: [],
  pedido: {
    productos: [],
    total: 0,
    entrega: '',
    nombre_cliente: '',
    direccion: '',
    referencia: '',
    con_cuanto_paga: 0
  }
};

return [{
  json: {
    ...$input.first().json,
    historial: cliente.historial,
    pedido:    cliente.pedido
  }
}];

const geminiResponse = $input.first().json;
const datosCliente = $('Armar prompt para Gemini').item.json;

const textoCompleto = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text || '';

const regexPedido = /##PEDIDO##(\{.*?\})##/s;
const matchPedido = textoCompleto.match(regexPedido);

let pedidoJSON = null;
let mensajeCliente = textoCompleto;

if (matchPedido) {
  try {
    pedidoJSON = JSON.parse(matchPedido[1]);
    pedidoJSON.numero_whatsapp = datosCliente.numero;
    pedidoJSON.telefono = pedidoJSON.telefono || datosCliente.numero.replace('521','').slice(-10);
    pedidoJSON.timestamp = new Date().toISOString();
  } catch (e) {
    pedidoJSON = null;
  }
  mensajeCliente = textoCompleto.replace(regexPedido, '').trim();
}

return [{
  json: {
    ...datosCliente,
    respuestBot:    mensajeCliente,
    pedidoCerrado:  pedidoJSON !== null,
    pedidoJSON
  }
}];

const datos = $('Procesar respuesta Gemini').item.json;
const staticData = $getWorkflowStaticData('global');

if (!staticData.clientes) staticData.clientes = {};

const cliente = staticData.clientes[datos.numero] || {
  historial: [],
  pedido: { productos: [], total: 0, entrega: '', nombre_cliente: '', direccion: '', referencia: '', con_cuanto_paga: 0 }
};

cliente.historial.push({ rol: 'cliente', texto: datos.texto });
cliente.historial.push({ rol: 'bot',     texto: datos.respuestBot });

if (cliente.historial.length > 30) cliente.historial = cliente.historial.slice(-30);

if (datos.pedidoCerrado && datos.pedidoJSON) {
  cliente.pedido = datos.pedidoJSON;
}

staticData.clientes[datos.numero] = cliente;

return [{ json: datos }];

const datos = $('Procesar respuesta Gemini').item.json;
const staticData = $getWorkflowStaticData('global');

if (staticData.clientes?.[datos.numero]) {
  staticData.clientes[datos.numero].pedido = {
    productos: [], total: 0, entrega: '',
    nombre_cliente: '', direccion: '', referencia: '', con_cuanto_paga: 0
  };
}

return [{ json: datos }];
